"""Generate the ADX-tier 16-limb Montgomery square and multiply that
stdlib/runtime_core.c carries between the markers

    /* ── generated by tools/gen_rsa_adx16.py — do not edit by hand ── */
    /* ── end of tools/gen_rsa_adx16.py ── */

    python3 tools/gen_rsa_adx16.py            # rewrite the block in place
    python3 tools/gen_rsa_adx16.py --check    # exit 1 if it is stale

RSA-2048's CRT halves are 16 limbs. On the ADX tier std/rsa_mont.nu
ran them as rows of nurl_mac_row (ADR 0001): fine for long rows, but a
square's cross-product rows are 15 … 1 limbs long, and per-row setup plus
the one-product loop for the n mod 4 leftovers made a square (376
products) cost as much as a multiply (512). Here every row is written
out — no loop control, no leftovers — and the Montgomery reduction is
blocked eight rows at a time: eight words of t live in registers, each
row's q = t[k]·n0 is parked in t[k] (a column the reduction zeroes
anyway) and reused for m's second eight limbs, so t moves through memory
once per eight rows instead of once per row.

The blocks need 13 operands plus rdx (mulx's implicit source): eight
window words, three temporaries, the source pointer and t. rbp stays free
for builds with frame pointers (the sanitizer runtime). The source
pointer is a, then m: both arrive through memory slots.

Every column sum is bounded the way the rows' are: a row of eight
products into a nine-word window cannot overflow it (W + q·m[0..8) <
2^576), and a slide adds at most one carry to the next column.
"""
import os
import re
import sys

N = 16
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
TARGET = os.path.join(ROOT, "stdlib", "runtime_core.c")
BEGIN = "/* ── generated by tools/gen_rsa_adx16.py — do not edit by hand ── */"
END = "/* ── end of tools/gen_rsa_adx16.py ── */"

# Operand numbers in the asm: %0..%7 window, %8 lo, %9 T, %10 CB, %11 src,
# %12 t, then the memory slots.
W = [f"%{i}" for i in range(8)]
LO, T0, CB, SRC, TP = "%8", "%9", "%10", "%11", "%12"


def redc(e, n, mslot, n0):
    """t[n..2n) + t[2n]·2^(64n) = t·R^-1 mod-ish m (the result before the
    final conditional subtract); t holds 2n + 1 words, t[2n] is scratch."""
    B = n // 8
    T = T0
    e(f"mov {mslot}, {SRC}")
    e(f"movq $0, {8 * 2 * n}({TP})")

    def row(win, moff):
        e(f"xor {LO}, {LO}")
        for j in range(8):
            e(f"mulx {8 * (moff + j)}({SRC}), {LO}, {T}")
            e(f"adcx {LO}, {win[j]}")
            if j < 7:
                e(f"adox {T}, {win[j + 1]}")
        e(f"mov $0, {LO}")
        e(f"adox {LO}, {T}")
        e(f"adcx {LO}, {T}")

    def slide(col):
        # T := t[col] + T + CB, CB := the carry out (at most one)
        e(f"xor {LO}, {LO}")
        e(f"adcx {8 * col}({TP}), {T}")
        e(f"adox {CB}, {T}")
        e(f"mov $0, {CB}")
        e(f"adcx {LO}, {CB}")
        e(f"adox {LO}, {CB}")

    regs = W[:]
    for b in range(B):
        win = regs[:]
        for j in range(8):
            e(f"mov {8 * (8 * b + j)}({TP}), {win[j]}")
        e(f"xor {CB}, {CB}")
        for r in range(8):
            k = 8 * b + r
            e(f"mov {win[0]}, %%rdx")
            e(f"imul {n0}, %%rdx")
            e(f"mov %%rdx, {8 * k}({TP})")
            row(win, 0)
            slide(k + 8)
            dead = win[0]
            win = win[1:] + [T]
            T = dead
        for c in range(1, B):
            for r in range(8):
                k = 8 * b + r
                col0 = 8 * (b + c) + r
                e(f"mov {8 * k}({TP}), %%rdx")
                row(win, 8 * c)
                e(f"mov {win[0]}, {8 * col0}({TP})")
                slide(col0 + 8)
                dead = win[0]
                win = win[1:] + [T]
                T = dead
        top = 8 * (b + B)
        for j in range(8):
            e(f"mov {win[j]}, {8 * (top + j)}({TP})")
        if top + 8 < 2 * n:
            e(f"add {CB}, {8 * (top + 8)}({TP})")
            for col in range(top + 9, 2 * n):
                e(f"adcq $0, {8 * col}({TP})")
            e(f"adcq $0, {8 * 2 * n}({TP})")
        else:
            e(f"add {CB}, {8 * 2 * n}({TP})")
        regs = win


def square(n):
    out = []
    e = out.append
    aslot, mslot, n0 = "%13", "%14", "%15"
    e(f"mov {aslot}, {SRC}")
    # cross products: row k adds a[k+1..n)·a[k] at 2k+1, its carry word at k+n
    for k in range(n - 1):
        e(f"mov {8 * k}({SRC}), %%rdx")
        e(f"xor {CB}, {CB}")
        hi_prev = None
        for idx, j in enumerate(range(k + 1, n)):
            col = k + j
            h = W[idx % 2]
            e(f"mulx {8 * j}({SRC}), {LO}, {h}")
            if k == 0:
                if hi_prev is not None:
                    e(f"adcx {hi_prev}, {LO}")
            else:
                e(f"adcx {8 * col}({TP}), {LO}")
                if hi_prev is not None:
                    e(f"adox {hi_prev}, {LO}")
            e(f"mov {LO}, {8 * col}({TP})")
            hi_prev = h
        e(f"adcx {CB}, {hi_prev}")
        e(f"adox {CB}, {hi_prev}")
        e(f"mov {hi_prev}, {8 * (k + n)}({TP})")
    e(f"movq $0, 0({TP})")
    e(f"movq $0, {8 * (2 * n - 1)}({TP})")
    # doubled, plus the squares on the diagonal; shld clobbers the flags,
    # so a pair's adds start fresh and the carry between pairs is W5
    e(f"xor {CB}, {CB}")
    e(f"xor {W[5]}, {W[5]}")
    for i in range(n):
        x0, x1, pn = W[2], W[3], W[4]
        e(f"mov {8 * (2 * i)}({TP}), {x0}")
        e(f"mov {8 * (2 * i + 1)}({TP}), {x1}")
        e(f"mov {x1}, {pn}")
        e(f"shld $1, {x0}, {x1}")
        e(f"shld $1, {CB}, {x0}")
        e(f"mov {pn}, {CB}")
        e(f"mov {8 * i}({SRC}), %%rdx")
        e(f"mulx %%rdx, {LO}, {T0}")
        e(f"add {LO}, {x0}")
        e(f"adc {T0}, {x1}")
        e(f"mov $0, {W[6]}")
        e(f"adc $0, {W[6]}")
        e(f"add {W[5]}, {x0}")
        e(f"adc $0, {x1}")
        e(f"adc $0, {W[6]}")
        e(f"mov {W[6]}, {W[5]}")
        e(f"mov {x0}, {8 * (2 * i)}({TP})")
        e(f"mov {x1}, {8 * (2 * i + 1)}({TP})")
    redc(e, n, mslot, n0)
    return out


def multiply(n):
    out = []
    e = out.append
    aslot, mslot, n0, bslot = "%13", "%14", "%15", "%16"
    e(f"mov {aslot}, {SRC}")
    for k in range(n):
        e(f"mov {bslot}, {W[2]}")
        e(f"mov {8 * k}({W[2]}), %%rdx")
        e(f"xor {CB}, {CB}")
        hi_prev = None
        for j in range(n):
            col = k + j
            h = W[j % 2]
            e(f"mulx {8 * j}({SRC}), {LO}, {h}")
            if k == 0:
                if hi_prev is not None:
                    e(f"adcx {hi_prev}, {LO}")
            else:
                e(f"adcx {8 * col}({TP}), {LO}")
                if hi_prev is not None:
                    e(f"adox {hi_prev}, {LO}")
            e(f"mov {LO}, {8 * col}({TP})")
            hi_prev = h
        e(f"adcx {CB}, {hi_prev}")
        e(f"adox {CB}, {hi_prev}")
        e(f"mov {hi_prev}, {8 * (k + n)}({TP})")
    redc(e, n, mslot, n0)
    return out


def constant_time(lines):
    """The blocks must be straight-line with fixed addresses: no branch
    (a jump, a loop, a conditional move on data would all show here) and
    no indexed operand — every address is a constant offset from t, a,
    b, m or the n0 slot, so neither control flow nor the address stream
    can depend on the operands' values."""
    for ln in lines:
        op = ln.split()[0]
        if op.startswith("j") or op.startswith("cmov") or op in ("loop", "call", "ret") or op.startswith("set"):
            raise SystemExit(f"gen_rsa_adx16: non-straight-line instruction: {ln}")
        if re.search(r"\(%[^)]*,", ln):
            raise SystemExit(f"gen_rsa_adx16: indexed addressing: {ln}")
    return lines


def c_asm(lines, indent):
    pad = " " * indent
    return "\n".join(f'{pad}"{ln}\\n\\t"' for ln in lines)


OUTS = ('"=&r"(w0), "=&r"(w1), "=&r"(w2), "=&r"(w3), "=&r"(w4), "=&r"(w5), "=&r"(w6), "=&r"(w7),\n'
        '          "=&r"(lo), "=&r"(hi), "=&r"(cb), "=&r"(src)')


def block():
    sq = c_asm(constant_time(square(N)), 8)
    mu = c_asm(constant_time(multiply(N)), 8)
    return f"""{BEGIN}
/* RSA-2048's 16-limb CRT halves on the ADX tier: a Montgomery square and
 * multiply as one straight-line block each (tools/gen_rsa_adx16.py says
 * how they are built). t holds 33 words: on return t[16..32) plus t[32]
 * as the bit above is x·y·R^-1 before the final conditional subtract —
 * exactly what std/rsa_mont.nu's rows leave for __rm_final. 1 when the
 * kernel ran; 0 on a CPU without BMI2 + ADX (or NURL_CPU_ADX=0) and on
 * every other target, where the caller keeps its rows. Constant time: no
 * branch, and every address depends on the indices alone. */
#if (defined(__x86_64__) || defined(_M_X64)) && (defined(__GNUC__) || defined(__clang__))
int nurl_rsa16_sqrm_adx(unsigned long long *t, const unsigned long long *a,
                        const unsigned long long *m, unsigned long long n0) {{
    if (!nurl_cpu_x86_adx()) return 0;
    const unsigned long long *aslot = a, *mslot = m;
    unsigned long long w0, w1, w2, w3, w4, w5, w6, w7, lo, hi, cb;
    const unsigned long long *src;
    __asm__ volatile(
{sq}
        : {OUTS}
        : "r"(t), "m"(aslot), "m"(mslot), "m"(n0)
        : "rdx", "cc", "memory");
    return 1;
}}

int nurl_rsa16_mulm_adx(unsigned long long *t, const unsigned long long *a,
                        const unsigned long long *b, const unsigned long long *m,
                        unsigned long long n0) {{
    if (!nurl_cpu_x86_adx()) return 0;
    const unsigned long long *aslot = a, *mslot = m, *bslot = b;
    unsigned long long w0, w1, w2, w3, w4, w5, w6, w7, lo, hi, cb;
    const unsigned long long *src;
    __asm__ volatile(
{mu}
        : {OUTS}
        : "r"(t), "m"(aslot), "m"(mslot), "m"(n0), "m"(bslot)
        : "rdx", "cc", "memory");
    return 1;
}}
#else
int nurl_rsa16_sqrm_adx(unsigned long long *t, const unsigned long long *a,
                        const unsigned long long *m, unsigned long long n0) {{
    (void)t; (void)a; (void)m; (void)n0;
    return 0;
}}

int nurl_rsa16_mulm_adx(unsigned long long *t, const unsigned long long *a,
                        const unsigned long long *b, const unsigned long long *m,
                        unsigned long long n0) {{
    (void)t; (void)a; (void)b; (void)m; (void)n0;
    return 0;
}}
#endif
{END}"""


def main(argv):
    src = open(TARGET, encoding="utf-8").read()
    if BEGIN not in src or END not in src:
        sys.stderr.write(f"gen_rsa_adx16: markers not found in {TARGET}\n")
        return 2
    i, j = src.index(BEGIN), src.index(END) + len(END)
    new = src[:i] + block() + src[j:]
    if "--check" in argv:
        if new != src:
            sys.stderr.write("gen_rsa_adx16: stdlib/runtime_core.c's generated block is stale; "
                             "run python3 tools/gen_rsa_adx16.py\n")
            return 1
        return 0
    if new != src:
        open(TARGET, "w", encoding="utf-8").write(new)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
